SELECT COUNT(*)
  FROM facility_sport fs
  JOIN facility f ON f.facility_id = fs.facility_id
                 AND f.deleted_at IS NULL
  JOIN facility_manager fm ON fm.facility_id = f.facility_id
                          AND fm.user_id = #{managerUserId}
 WHERE fs.facility_id = #{facilityId}
   AND fs.sport_id = #{sportId}

